async function api(path:string,body?:unknown,method?:string,signal?:AbortSignal){const res=await fetch(path,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal});const data:any=await res.json();if(!res.ok)throw new Error(data.error||'操作失败');return data;}
function download(name:string,text:string,type='text/markdown'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function Pick({value,onChange,options,placeholder,className}:any){return <Select value={value||'_none'} onValueChange={v=>onChange(v==='_none'?'':v)}><SelectTrigger className={className} aria-label={placeholder}><SelectValue placeholder={placeholder}/></SelectTrigger><SelectContent><SelectItem value="_none">{placeholder}</SelectItem>{options.map((o:any)=><SelectItem key={o.id} value={o.id}>{o.name}</SelectItem>)}</SelectContent></Select>;}
function RichText({text}:{text:string}){return <div className="rich-text">{text.split(/(```[\s\S]*?```)/g).map((part,i)=>part.startsWith('```')?<pre key={i}><code>{part.replace(/^```[^\n]*\n?/,'').replace(/```$/,'')}</code></pre>:part.split('\n').map((line,j)=>{const heading=line.match(/^(#{1,4})\s+(.*)/);if(heading)return <h3 key={`${i}-${j}`}>{heading[2]}</h3>;if(!line.trim())return <div key={`${i}-${j}`} className="paragraph-gap"/>;return <p key={`${i}-${j}`}>{line.split(/(\*\*[^*]+\*\*)/g).map((s,k)=>s.startsWith('**')?<strong key={k}>{s.slice(2,-2)}</strong>:s)}</p>;}))}</div>;}
function Mark(){return <span className="brand-mark"><Layers size={23}/></span>;}
function NavButton({item,active,go}:any){const {setOpenMobile}=useSidebar();return <SidebarMenuItem><SidebarMenuButton isActive={active} onClick={()=>{go(item.id);setOpenMobile(false);}}><item.icon/><span>{item.name}</span>{active&&<ChevronRight className="ml-auto" size={14}/>}</SidebarMenuButton></SidebarMenuItem>;}
function Empty({icon:Icon,title,desc,children}:any){return <div className="empty-state"><span className="empty-icon"><Icon size={28}/></span><h3>{title}</h3><p>{desc}</p>{children}</div>;}
