 async function refresh(activeChatId=chatId){const d=await api('/api/workspace');setRecords(d.records);setDeletedChats(d.deletedChats||[]);setDocs(d.documents);setUsage(d.usage);setVaultIds(d.vault||[]);setLoadError('');setProfileId(p=>d.records.some((r:Item)=>r.id===p&&r.kind==='profile')?p:d.records.find((r:Item)=>r.kind==='profile')?.id||'');if(activeChatId){const active=d.records.find((r:Item)=>r.id===activeChatId&&r.kind==='chat');if(active)setChatUpdated(active.updated);}return d;}
