 async function save(kind:string,data:any,id=crypto.randomUUID()){if(kind==='chat'){try{await saveChat(data,id);}catch(e:any){if(e.message?.includes('另一页面'))await reloadChat(id).catch(()=>{});throw e;}return id;}await api('/api/workspace',{id,kind,data});return id;}
